using System;using System.IO;using System.Collections.Generic;using UnityEngine;
public class Script{public static string Main(){var rows=new List<object>();foreach(var random in new[]{0f,.1f})foreach(var spherical in new[]{0f,.1f}){var go=new GameObject("edge-dir"){hideFlags=HideFlags.HideAndDontSave};try{var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var m=ps.main;m.startLifetime=10;m.startSpeed=1;var e=ps.emission;e.enabled=false;var sh=ps.shape;sh.enabled=true;sh.shapeType=ParticleSystemShapeType.SingleSidedEdge;sh.radius=1;sh.randomPositionAmount=.3f;sh.radiusMode=ParticleSystemShapeMultiModeValue.Loop;sh.radiusSpeed=0;sh.randomDirectionAmount=random;sh.sphericalDirectionAmount=spherical;ps.useAutoRandomSeed=false;ps.randomSeed=12345;ps.Play();ps.Pause();ps.Emit(64);var p=new ParticleSystem.Particle[64];ps.GetParticles(p);var vs=new List<object>();foreach(var v in p)vs.Add(new{position=new[]{v.position.x,v.position.y,v.position.z},velocity=new[]{v.velocity.x,v.velocity.y,v.velocity.z}});rows.Add(new{random,spherical,velocity=vs});}finally{UnityEngine.Object.DestroyImmediate(go);}}File.WriteAllText("OUTPUT_FILE",System.Text.Json.JsonSerializer.Serialize(new{isPlaying=Application.isPlaying,rows}));return "Edge direction captured";}}

